import{_ as e,o as i,c as t,a0 as l}from"./chunks/framework.DZqO77tS.js";const p=JSON.parse('{"title":"はじめ方","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),r={name:"guide/getting-started.md"};function o(n,a,s,c,d,h){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="はじめ方" tabindex="-1">はじめ方 <a class="header-anchor" href="#はじめ方" aria-label="Permalink to &quot;はじめ方&quot;">​</a></h1><p>ようこそ！このページでは、約 15〜20 分で <strong>最初の成功</strong> まで進めます。</p><h2 id="用意するもの" tabindex="-1">用意するもの <a class="header-anchor" href="#用意するもの" aria-label="Permalink to &quot;用意するもの&quot;">​</a></h2><ul><li>EcoCONNECT のメインボード</li><li>ボードに合う USB ケーブル</li><li>パソコン（Windows / macOS / Linux）</li></ul><p>あれば便利：観察メモ用のノート</p><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-ボードを確認する" tabindex="-1">1. ボードを確認する <a class="header-anchor" href="#_1-ボードを確認する" aria-label="Permalink to &quot;1. ボードを確認する&quot;">​</a></h3><p>ボードを一度ながめて、次を探します。</p><ul><li>USB コネクタ</li><li>メインのチップ周辺（Raspberry Pi Pico）</li><li>センサー用のコネクタ（ラベルがある場合）</li></ul><p>破損していそうなら、電源を入れず先生やメンターに相談してください。</p><h3 id="_2-電源をつなぐ" tabindex="-1">2. 電源をつなぐ <a class="header-anchor" href="#_2-電源をつなぐ" aria-label="Permalink to &quot;2. 電源をつなぐ&quot;">​</a></h3><ol><li>USB ケーブルをボードにさす</li><li>もう一端をパソコンにさす</li><li>電源ランプ（LED など）があれば点灯を確認</li></ol><h3 id="_3-用意済みファームウェアを書き込む-初心者向け" tabindex="-1">3. 用意済みファームウェアを書き込む（初心者向け） <a class="header-anchor" href="#_3-用意済みファームウェアを書き込む-初心者向け" aria-label="Permalink to &quot;3. 用意済みファームウェアを書き込む（初心者向け）&quot;">​</a></h3><p>EcoCONNECT には、コードを書かなくても使える <strong>書き込み用イメージ</strong> があります。</p><ol><li>リポジトリの <code>firmware/pico2/release/</code> を開く</li><li><code>firmware/pico2/</code> の README に従い、<code>.uf2</code> を Raspberry Pi Pico にコピーする</li><li>ボードが再起動したら、最初の計測の準備完了です</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>書き込みでつまずいたらメンターに聞いてください。はじめての人によくあるステップで、いっしょならすぐ解決できます。</p></div><h3 id="_4-最初の計測へ" tabindex="-1">4. 最初の計測へ <a class="header-anchor" href="#_4-最初の計測へ" aria-label="Permalink to &quot;4. 最初の計測へ&quot;">​</a></h3><p>つづきは <a href="/AuraLinc-Community/tutorials/first-reading">はじめてのセンサー計測</a> へ。</p><h2 id="次にやってみよう" tabindex="-1">次にやってみよう <a class="header-anchor" href="#次にやってみよう" aria-label="Permalink to &quot;次にやってみよう&quot;">​</a></h2><ul><li>10 分で終わる <a href="/AuraLinc-Community/recipes/">レシピ</a></li><li>アイデア探しは <a href="/AuraLinc-Community/examples/">事例</a></li><li>先生向け：<a href="/AuraLinc-Community/steam/">STEAM の授業アイデア</a></li></ul>',20)])])}const m=e(r,[["render",o]]);export{p as __pageData,m as default};
